//! C020 evidence campaign: *agent repairs do not weaken properties/assumptions
//! silently* (`notes/plan/docs/18_CLAIMS_MATRIX.md`, C020; required evidence:
//! "semantic diff and hidden-mutant evaluation"; bn-bpz0).
//!
//! # What this file measures
//!
//! A held-out corpus of agent-style weakening edits over every committed Intent
//! Contract, generated by a seeded generator (`support/c020_mutant_generator.rs`)
//! that is written apart from the classifier. Each after-document goes through the
//! production front door (`IntentContract::decode`) and the production diff
//! assembler (`continuum_semantic_diff::artifact::assemble`), which classifies all
//! fifteen protected fields and closes the result with
//! `PolicyTable::verdict` on the agent acceptance path. The metric is the one the
//! claim needs:
//!
//! - **flagged** — every field the edit moves carries a wire record whose relation
//!   is not in that direction's benign set (for a property weakening, anything other
//!   than `unchanged`/`strengthened`/`added`; the table is [`benign`]);
//! - **not silent** — the verdict under a locked policy is `review` or `block`, at
//!   the `bounded` requested assurance and again at `observed`, where the
//!   assembler's clamp turns every expression direction into `unknown`.
//!
//! A mutant that fails either is a **miss**. The claim needs zero misses, and every
//! miss is printed with its id and its after-document.
//!
//! # The two policies
//!
//! - **Locked** — the before-contract's policy table with every one of the fifteen
//!   verbs set to `locked`. This is the claim's measurement policy: a locked-spec
//!   agent benchmark.
//! - **Own** — each contract's committed table. Reported, not asserted: a verb such
//!   as `unlocked` or `no-downgrade` admits some classified changes by the owner's
//!   declaration, and the ledger lists every such `allow` with its field and verb.
//!
//! The verdict is always computed against the *before* table (RFC 0037 P7), so an
//! edit that also unlocks its own field (the `*-unlock-rider+*` operators) cannot
//! lift its own block.
//!
//! # Hidden, and in what sense
//!
//! No classifier code or classifier test was tuned on this corpus. The generator
//! does not import the classifier crate or the policy vocabulary (a source guard
//! below pins that), its ground truth is by construction (the polarity rule), and
//! the primary seed was fixed before the first run. A second sweep over sixteen
//! further seeds is asserted on aggregates only, and its per-mutant rows are never
//! retained or inspected.
//!
//! # What this file does not measure
//!
//! The repair layer. RFC 0032 repair transactions and Forge are not implemented, so
//! there is no agent repair to run. This file measures the classification and
//! policy layer that any repair must pass through (INV-011: a repair transaction
//! cannot be promoted if it changes protected intent unless it is reclassified).
//!
//! The retained ledger is `tests/golden/c020_hidden_mutant_evidence.txt`. The test
//! writes the rendered ledger to `$CARGO_TARGET_TMPDIR` before it compares it, so a
//! deliberate refresh is a copy of that file.

#[path = "support/c020_mutant_generator.rs"]
mod generator;

use std::collections::BTreeMap;
use std::fmt::Write as _;
use std::path::{Path, PathBuf};

use continuum_intent::assurance_policy::AssuranceLevel;
use continuum_intent::canonical_json::Json;
use continuum_intent::change_policy::{AcceptancePath, PolicyDecision, PolicyField, Relation};
use continuum_intent::contract::{IntentContract, IntentId};
use continuum_semantic_diff::artifact::{DiffId, DiffRequest, SnapshotId, assemble};

use generator::{Base, Direction, Expectation, Field, Mutant, OPERATORS, generate};

/// The primary seed. Fixed before the first run and never changed to suit a result.
const SEED: u64 = 0xC020_5EED_0000_0001;
/// Distinct variants per (base, operator) in the primary corpus.
const VARIANTS: usize = 4;
/// The held-out sweep: aggregates only.
const HELD_OUT_SEEDS: [u64; 16] = [
    0xC020_0000_0000_0010,
    0xC020_0000_0000_0011,
    0xC020_0000_0000_0012,
    0xC020_0000_0000_0013,
    0xC020_0000_0000_0014,
    0xC020_0000_0000_0015,
    0xC020_0000_0000_0016,
    0xC020_0000_0000_0017,
    0xC020_0000_0000_0018,
    0xC020_0000_0000_0019,
    0xC020_0000_0000_001A,
    0xC020_0000_0000_001B,
    0xC020_0000_0000_001C,
    0xC020_0000_0000_001D,
    0xC020_0000_0000_001E,
    0xC020_0000_0000_001F,
];
const HELD_OUT_VARIANTS: usize = 2;

/// The T09 baseline pins every committed Intent Contract exactly once
/// (`crates/continuum-intent/tests/t09_property_baseline.rs`), so its entry list is
/// the corpus of real contracts.
const BASELINE: &str = include_str!("../../../tools/governance/t09-property-baseline.json");
const GOLDEN: &str = include_str!("golden/c020_hidden_mutant_evidence.txt");
const GENERATOR_SOURCE: &str = include_str!("support/c020_mutant_generator.rs");

// --- bases ---------------------------------------------------------------------------------

fn repo_root() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("../..")
        .canonicalize()
        .expect("the repository root resolves")
}

fn object_field<'a>(json: &'a Json, key: &str) -> &'a Json {
    json.as_object()
        .and_then(|map| map.get(key))
        .unwrap_or_else(|| panic!("missing {key:?}"))
}

fn label_of(path: &str) -> String {
    let stem = Path::new(path)
        .file_name()
        .and_then(|name| name.to_str())
        .expect("a file name");
    stem.trim_end_matches(".json")
        .trim_end_matches("-contract")
        .replace('.', "-")
}

/// The committed contracts, in baseline order, as `(label, document)`.
fn bases() -> Vec<Base> {
    let baseline = Json::parse(BASELINE.as_bytes()).expect("the T09 baseline parses");
    let entries = object_field(&baseline, "entries")
        .as_array()
        .expect("entries is an array");
    let root = repo_root();
    entries
        .iter()
        .map(|entry| {
            let path = object_field(entry, "path").as_str().expect("a path");
            let text = std::fs::read_to_string(root.join(path))
                .unwrap_or_else(|e| panic!("{path} is readable: {e}"));
            Base {
                label: label_of(path),
                document: Json::parse(text.trim_end().as_bytes())
                    .unwrap_or_else(|e| panic!("{path} parses: {e:?}")),
            }
        })
        .collect()
}

/// The before-document under the locked measurement policy.
fn locked(document: &Json) -> Json {
    let mut out = document.clone();
    if let Json::Object(map) = &mut out {
        if let Some(Json::Object(policy)) = map.get_mut("policy") {
            for verb in policy.values_mut() {
                *verb = Json::String("locked".to_owned());
            }
        }
    }
    out
}

fn decode(document: &Json) -> Result<IntentContract, String> {
    IntentContract::decode(&document.to_canonical_bytes()).map_err(|e| format!("{e:?}"))
}

// --- running one mutant ----------------------------------------------------------------------

#[derive(Debug, Clone, PartialEq, Eq)]
struct Record {
    field: PolicyField,
    unit: Option<String>,
    relation: Relation,
}

#[derive(Debug, Clone, PartialEq, Eq)]
enum Outcome {
    /// The after-document did not decode. Nothing reached the classifier, so
    /// nothing was allowed.
    RejectedAtDecode(String),
    /// The assembler refused the artifact (P1/W7/inadmissible relation).
    Refused(String),
    Assembled {
        records: Vec<Record>,
        locked: PolicyDecision,
        locked_observed: PolicyDecision,
        own: PolicyDecision,
    },
}

fn request<'a>(
    before: &'a IntentContract,
    after: &'a IntentContract,
    requested: AssuranceLevel,
) -> DiffRequest<'a> {
    DiffRequest {
        diff_id: DiffId::new("diff_c020_hidden_mutant").expect("well formed"),
        before_snapshot: SnapshotId::new("ws_c020_before").expect("well formed"),
        after_snapshot: SnapshotId::new("ws_c020_after").expect("well formed"),
        before_intent: IntentId::new("in_c020_before").expect("well formed"),
        after_intent: IntentId::new("in_c020_after").expect("well formed"),
        before,
        after,
        requested_assurance: requested,
        path: AcceptancePath::AgentAccept,
        semantic_changes: Vec::new(),
        evidence: Vec::new(),
    }
}

struct Prepared {
    own: IntentContract,
    locked: IntentContract,
}

fn prepare(base: &Base) -> Prepared {
    Prepared {
        own: decode(&base.document).expect("the committed contract decodes"),
        locked: decode(&locked(&base.document)).expect("the locked variant decodes"),
    }
}

fn run(prepared: &Prepared, mutant: &Mutant) -> Outcome {
    let after = match decode(&mutant.document) {
        Ok(after) => after,
        Err(e) => return Outcome::RejectedAtDecode(e),
    };
    let locked_artifact =
        match assemble(&request(&prepared.locked, &after, AssuranceLevel::Bounded)) {
            Ok(artifact) => artifact,
            Err(e) => return Outcome::Refused(format!("{e:?}")),
        };
    let locked_observed =
        match assemble(&request(&prepared.locked, &after, AssuranceLevel::Observed)) {
            Ok(artifact) => artifact.decision(),
            Err(e) => return Outcome::Refused(format!("{e:?}")),
        };
    let own = match assemble(&request(&prepared.own, &after, AssuranceLevel::Bounded)) {
        Ok(artifact) => artifact.decision(),
        Err(e) => return Outcome::Refused(format!("{e:?}")),
    };
    Outcome::Assembled {
        records: locked_artifact
            .intent_changes()
            .iter()
            .map(|record| Record {
                field: record.field(),
                unit: record.unit().map(str::to_owned),
                relation: record.relation(),
            })
            .collect(),
        locked: locked_artifact.decision(),
        locked_observed,
        own,
    }
}

// --- scoring -------------------------------------------------------------------------------

const fn policy_field(field: Field) -> PolicyField {
    match field {
        Field::Properties => PolicyField::Properties,
        Field::Assumptions => PolicyField::Assumptions,
        Field::Bounds => PolicyField::Bounds,
        Field::Observers => PolicyField::Observers,
        Field::Faults => PolicyField::Faults,
        Field::Fairness => PolicyField::Fairness,
        Field::Assurance => PolicyField::Assurance,
    }
}

/// The relations that would read an edit of this direction as harmless. A target
/// is flagged only by a record *outside* this set.
const fn benign(direction: Direction) -> &'static [Relation] {
    match direction {
        Direction::WeakensProperty => {
            &[Relation::Unchanged, Relation::Strengthened, Relation::Added]
        }
        Direction::StrengthensAssumption | Direction::StrengthensFairness => {
            &[Relation::Unchanged, Relation::Weakened, Relation::Removed]
        }
        Direction::ShrinksBound => &[Relation::Unchanged, Relation::Expanded],
        Direction::CoarsensObserver => &[Relation::Unchanged, Relation::Refined, Relation::Added],
        Direction::RemovesFault => &[Relation::Unchanged, Relation::Added],
        Direction::DowngradesAssurance => &[Relation::Unchanged, Relation::Upgraded],
        Direction::ChangesFairness | Direction::ChangesAssurance => &[Relation::Unchanged],
    }
}

/// The exact affirmed relation each direction names, when the classifier derives
/// one (as opposed to failing closed to `unknown`/`incomparable`/`unsupported`).
const fn affirmed(direction: Direction) -> &'static [Relation] {
    match direction {
        Direction::WeakensProperty => &[Relation::Weakened, Relation::Removed],
        Direction::StrengthensAssumption | Direction::StrengthensFairness => {
            &[Relation::Strengthened, Relation::Added]
        }
        Direction::ShrinksBound => &[Relation::Contracted],
        Direction::CoarsensObserver => &[Relation::Coarsened, Relation::Removed],
        Direction::RemovesFault => &[Relation::Removed],
        Direction::DowngradesAssurance => &[Relation::Downgraded],
        Direction::ChangesFairness => &[Relation::Removed],
        Direction::ChangesAssurance => &[Relation::Added],
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum Grade {
    /// A weakening: every target flagged, never allowed under the locked policy.
    Caught { affirmed: bool },
    /// A weakening that failed the metric. The reason says how.
    Miss(&'static str),
    /// A weakening that never reached the classifier (decode rejection). Safe, and
    /// counted apart so it cannot inflate the flagged count.
    RejectedAtDoor,
    /// A control that classified fifteen `unchanged` and was allowed.
    ControlAllowed,
    /// A control that was flagged: a precision loss, not a C020 defect.
    ControlFlagged,
}

fn grade(expectation: &Expectation, outcome: &Outcome) -> Grade {
    match (expectation, outcome) {
        (Expectation::Weakening(_), Outcome::RejectedAtDecode(_)) => Grade::RejectedAtDoor,
        (Expectation::Weakening(_), Outcome::Refused(_)) => Grade::Miss("assembler refused"),
        (
            Expectation::Weakening(targets),
            Outcome::Assembled {
                records,
                locked,
                locked_observed,
                ..
            },
        ) => {
            if *locked == PolicyDecision::Allow {
                return Grade::Miss("silent pass: allow under the locked policy");
            }
            if *locked_observed == PolicyDecision::Allow {
                return Grade::Miss("silent pass: allow under the locked policy at observed");
            }
            let mut all_affirmed = true;
            for target in targets {
                let field = policy_field(target.field);
                let on_field: Vec<Relation> = records
                    .iter()
                    .filter(|record| record.field == field)
                    .map(|record| record.relation)
                    .collect();
                if !on_field
                    .iter()
                    .any(|relation| !benign(target.direction).contains(relation))
                {
                    return Grade::Miss("target field not flagged");
                }
                if !on_field
                    .iter()
                    .any(|relation| affirmed(target.direction).contains(relation))
                {
                    all_affirmed = false;
                }
            }
            Grade::Caught {
                affirmed: all_affirmed,
            }
        }
        (
            Expectation::Control,
            Outcome::Assembled {
                records, locked, ..
            },
        ) if records.is_empty() && *locked == PolicyDecision::Allow => Grade::ControlAllowed,
        (Expectation::Control, _) => Grade::ControlFlagged,
    }
}

// --- the campaign ----------------------------------------------------------------------------

struct Row {
    mutant: Mutant,
    outcome: Outcome,
    grade: Grade,
    own_allow_verbs: Vec<String>,
}

fn campaign(seed: u64, variants: usize) -> Vec<Row> {
    let bases = bases();
    let prepared: BTreeMap<String, Prepared> = bases
        .iter()
        .map(|base| (base.label.clone(), prepare(base)))
        .collect();
    generate(seed, &bases, variants)
        .into_iter()
        .map(|mutant| {
            let prep = &prepared[&mutant.base];
            let outcome = run(prep, &mutant);
            let grade = grade(&mutant.expectation, &outcome);
            let own_allow_verbs = match (&mutant.expectation, &outcome) {
                (
                    Expectation::Weakening(_),
                    Outcome::Assembled {
                        records,
                        own: PolicyDecision::Allow,
                        ..
                    },
                ) => {
                    let mut verbs: Vec<String> = records
                        .iter()
                        .map(|record| {
                            format!(
                                "{}:{}",
                                record.field.wire(),
                                prep.own.policy().verb(record.field).wire()
                            )
                        })
                        .collect();
                    verbs.sort();
                    verbs.dedup();
                    verbs
                }
                _ => Vec::new(),
            };
            Row {
                mutant,
                outcome,
                grade,
                own_allow_verbs,
            }
        })
        .collect()
}

fn fnv1a(bytes: &[u8], mut hash: u64) -> u64 {
    for byte in bytes {
        hash ^= u64::from(*byte);
        hash = hash.wrapping_mul(0x0100_0000_01b3);
    }
    hash
}

fn corpus_fingerprint(rows: &[Row]) -> u64 {
    rows.iter().fold(0xcbf2_9ce4_8422_2325, |hash, row| {
        let hash = fnv1a(row.mutant.id.as_bytes(), hash);
        fnv1a(&row.mutant.document.to_canonical_bytes(), hash)
    })
}

fn expectation_text(expectation: &Expectation) -> String {
    match expectation {
        Expectation::Control => "control".to_owned(),
        Expectation::Weakening(targets) => targets
            .iter()
            .map(|t| format!("{:?}/{:?}", t.field, t.direction))
            .collect::<Vec<_>>()
            .join("+"),
    }
}

fn records_text(records: &[Record]) -> String {
    if records.is_empty() {
        return "-".to_owned();
    }
    records
        .iter()
        .map(|r| match &r.unit {
            Some(unit) if unit.starts_with("c020_") || unit.contains("_c020_") => {
                format!("{}[fresh]:{}", r.field.wire(), r.relation.wire())
            }
            Some(unit) => format!("{}[{unit}]:{}", r.field.wire(), r.relation.wire()),
            None => format!("{}:{}", r.field.wire(), r.relation.wire()),
        })
        .collect::<Vec<_>>()
        .join(",")
}

fn grade_text(grade: Grade) -> &'static str {
    match grade {
        Grade::Caught { affirmed: true } => "caught-affirmed",
        Grade::Caught { affirmed: false } => "caught-fail-closed",
        Grade::Miss(reason) => reason,
        Grade::RejectedAtDoor => "rejected-at-decode",
        Grade::ControlAllowed => "control-allowed",
        Grade::ControlFlagged => "control-flagged",
    }
}

#[derive(Default)]
struct Tally {
    weakening: usize,
    caught: usize,
    affirmed: usize,
    rejected: usize,
    misses: usize,
    silent: usize,
    controls: usize,
    controls_allowed: usize,
    own_allow: usize,
}

fn tally<'a>(rows: impl IntoIterator<Item = &'a Row>) -> Tally {
    let mut t = Tally::default();
    for row in rows {
        match row.mutant.expectation {
            Expectation::Weakening(_) => t.weakening += 1,
            Expectation::Control => t.controls += 1,
        }
        match row.grade {
            Grade::Caught { affirmed } => {
                t.caught += 1;
                t.affirmed += usize::from(affirmed);
            }
            Grade::Miss(reason) => {
                t.misses += 1;
                t.silent += usize::from(reason.starts_with("silent"));
            }
            Grade::RejectedAtDoor => t.rejected += 1,
            Grade::ControlAllowed => t.controls_allowed += 1,
            Grade::ControlFlagged => {}
        }
        t.own_allow += usize::from(!row.own_allow_verbs.is_empty());
    }
    t
}

fn decision_text(decision: PolicyDecision) -> &'static str {
    decision.wire()
}

fn render(rows: &[Row]) -> String {
    let mut out = String::new();
    let t = tally(rows);
    let _ = writeln!(
        out,
        "# C020 hidden-mutant evaluation: agent-style weakening edits over the committed Intent Contracts"
    );
    let _ = writeln!(
        out,
        "# crates/continuum-semantic-diff/tests/c020_hidden_mutant_evaluation.rs (bn-bpz0)"
    );
    let _ = writeln!(
        out,
        "# generator: tests/support/c020_mutant_generator.rs; seed {SEED:#018x}; variants {VARIANTS}; operators {}",
        OPERATORS.len()
    );
    let _ = writeln!(
        out,
        "# corpus fingerprint (FNV-1a 64 over id and canonical after-document, in order): {:016x}",
        corpus_fingerprint(rows)
    );
    let _ = writeln!(
        out,
        "# classification: continuum_semantic_diff::artifact::assemble; verdict: PolicyTable::verdict against the before table, AgentAccept"
    );
    let _ = writeln!(
        out,
        "# columns: id | expectation | grade | records (locked run, bounded) | locked | locked@observed | own"
    );
    for row in rows {
        let (records, locked, observed, own) = match &row.outcome {
            Outcome::Assembled {
                records,
                locked,
                locked_observed,
                own,
            } => (
                records_text(records),
                decision_text(*locked),
                decision_text(*locked_observed),
                decision_text(*own),
            ),
            Outcome::RejectedAtDecode(reason) => (
                format!(
                    "rejected at decode: {}",
                    reason.chars().take(96).collect::<String>()
                ),
                "-",
                "-",
                "-",
            ),
            Outcome::Refused(_) => ("refused".to_owned(), "-", "-", "-"),
        };
        let _ = writeln!(
            out,
            "{} | {} | {} | {records} | {locked} | {observed} | {own}",
            row.mutant.id,
            expectation_text(&row.mutant.expectation),
            grade_text(row.grade),
        );
    }
    let _ = writeln!(out, "# summary");
    let _ = writeln!(
        out,
        "mutants {} = weakening {} + control {}",
        rows.len(),
        t.weakening,
        t.controls
    );
    let _ = writeln!(
        out,
        "weakening: caught {} (affirmed direction {}, fail-closed {}), rejected-at-decode {}, misses {}, silent passes {}",
        t.caught,
        t.affirmed,
        t.caught - t.affirmed,
        t.rejected,
        t.misses,
        t.silent
    );
    let _ = writeln!(
        out,
        "controls: allowed {} of {}",
        t.controls_allowed, t.controls
    );
    let _ = writeln!(
        out,
        "own committed policy: {} weakening mutants allowed by an owner verb (listed below)",
        t.own_allow
    );
    let _ = writeln!(
        out,
        "# per operator: operator | n | caught | affirmed | rejected | misses | own-allow"
    );
    for operator in OPERATORS {
        let of: Vec<&Row> = rows
            .iter()
            .filter(|r| r.mutant.operator == operator)
            .collect();
        let sub = tally(of.iter().copied());
        let _ = writeln!(
            out,
            "{operator} | {} | {} | {} | {} | {} | {}",
            of.len(),
            sub.caught,
            sub.affirmed,
            sub.rejected,
            sub.misses,
            sub.own_allow
        );
    }
    let _ = writeln!(out, "# own-policy allows: id | field:own-verb");
    for row in rows.iter().filter(|r| !r.own_allow_verbs.is_empty()) {
        let _ = writeln!(out, "{} | {}", row.mutant.id, row.own_allow_verbs.join(","));
    }
    out
}

/// The held-out sweep's aggregates: one line, no per-mutant rows.
fn held_out_summary() -> (Tally, String) {
    let mut total = Tally::default();
    for seed in HELD_OUT_SEEDS {
        let t = tally(&campaign(seed, HELD_OUT_VARIANTS));
        total.weakening += t.weakening;
        total.caught += t.caught;
        total.affirmed += t.affirmed;
        total.rejected += t.rejected;
        total.misses += t.misses;
        total.silent += t.silent;
        total.controls += t.controls;
        total.controls_allowed += t.controls_allowed;
        total.own_allow += t.own_allow;
    }
    let line = format!(
        "held-out sweep: {} seeds x {HELD_OUT_VARIANTS} variants; weakening {}, caught {} (affirmed {}), rejected-at-decode {}, misses {}, silent passes {}; controls allowed {} of {}",
        HELD_OUT_SEEDS.len(),
        total.weakening,
        total.caught,
        total.affirmed,
        total.rejected,
        total.misses,
        total.silent,
        total.controls_allowed,
        total.controls
    );
    (total, line)
}

fn miss_report(rows: &[Row]) -> String {
    let mut out = String::new();
    for row in rows {
        if matches!(row.grade, Grade::Miss(_) | Grade::ControlFlagged) {
            let _ = writeln!(
                out,
                "{} [{}] {:?}\n  after: {}",
                row.mutant.id,
                grade_text(row.grade),
                row.outcome,
                String::from_utf8_lossy(&row.mutant.document.to_canonical_bytes())
            );
        }
    }
    out
}

// --- tests ---------------------------------------------------------------------------------

#[test]
fn the_hidden_corpus_has_zero_silent_passes_and_zero_misses() {
    let rows = campaign(SEED, VARIANTS);
    let t = tally(&rows);
    assert!(
        t.weakening >= 300,
        "the corpus is not trivially small: {}",
        t.weakening
    );
    assert_eq!(
        t.misses,
        0,
        "every miss is a candidate INV-001 defect:\n{}",
        miss_report(&rows)
    );
    assert_eq!(t.silent, 0);
    // A weakening rejected at the door is safe, but it is not evidence about the
    // classifier. Keep that share honest and small.
    assert!(
        t.rejected * 20 <= t.weakening,
        "too many mutants never reached the classifier: {} of {}",
        t.rejected,
        t.weakening
    );
}

#[test]
fn the_held_out_seed_sweep_has_zero_silent_passes_and_zero_misses() {
    for seed in HELD_OUT_SEEDS {
        let rows = campaign(seed, HELD_OUT_VARIANTS);
        assert_eq!(
            tally(&rows).misses,
            0,
            "held-out seed {seed:#x}: every miss is a candidate INV-001 defect:\n{}",
            miss_report(&rows)
        );
    }
    let (total, line) = held_out_summary();
    assert!(
        total.weakening >= 1000,
        "the held-out sweep is not trivially small: {line}"
    );
    assert_eq!(total.silent, 0, "{line}");
    assert_eq!(total.controls_allowed, total.controls, "{line}");
}

#[test]
fn the_controls_are_allowed_so_the_metric_can_discriminate() {
    // A classifier that blocks everything would pass the zero-miss test. The
    // controls are meaning-preserving edits (reorder, prose, name, a double
    // negation of an atom) and must classify fifteen `unchanged` and be allowed.
    let rows = campaign(SEED, VARIANTS);
    let t = tally(&rows);
    assert!(t.controls >= 20, "controls: {}", t.controls);
    assert_eq!(
        t.controls_allowed,
        t.controls,
        "flagged controls:\n{}",
        miss_report(&rows)
    );
}

#[test]
fn the_evidence_ledger_is_byte_stable_and_matches_the_golden() {
    let actual = format!(
        "{}{}\n",
        render(&campaign(SEED, VARIANTS)),
        held_out_summary().1
    );
    // `CARGO_TARGET_TMPDIR` is a compile-time constant: cargo creates it when it
    // (re)builds this test binary, not on every later `cargo test` run of an
    // already-built one, so a cached binary over an emptied target directory
    // (bn-1gibz) hits this write, not the assertion below, with ENOENT.
    let dir = Path::new(env!("CARGO_TARGET_TMPDIR"));
    std::fs::create_dir_all(dir)
        .unwrap_or_else(|error| panic!("{} is not creatable: {error}", dir.display()));
    let out = dir.join("c020_hidden_mutant_evidence.txt");
    std::fs::write(&out, &actual).expect("the rendered ledger is writable");
    assert!(
        actual == GOLDEN,
        "the C020 ledger drifted; the rendered ledger is at {}",
        out.display()
    );
    assert_eq!(
        actual,
        format!(
            "{}{}\n",
            render(&campaign(SEED, VARIANTS)),
            held_out_summary().1
        ),
        "INV-005"
    );
}

#[test]
fn the_corpus_covers_the_seven_g3_dimensions_and_every_named_disguise() {
    // Plan §5.3's seven G3 dimensions and the disguises the bone names. Each must
    // produce at least one mutant that reached the classifier.
    let required = [
        "prop-join-fresh",
        "prop-complementary-disjunct",
        "prop-drop-junct",
        "prop-remove-claim",
        "prop-rename+weaken",
        "prop-reorder+weaken",
        "prop-double-negation+weaken",
        "prop-vacuous-conjunct+weaken",
        "prop-unlock-rider+weaken",
        "asm-conjoin-fresh",
        "asm-add-assumption",
        "asm-rename+strengthen",
        "asm-double-negation+strengthen",
        "asm-vacuous-conjunct+strengthen",
        "bnd-shrink",
        "bnd-shrink+grow-other",
        "obs-drop-element",
        "obs-swap-element",
        "obs-rename+coarsen",
        "flt-remove-class",
        "flt-swap-class",
        "fair-add",
        "fair-weak-to-strong",
        "fair-remove",
        "asr-lower-minimum",
        "asr-raise-minimum+drop-flag",
        "cmp-two-fields",
    ];
    let rows = campaign(SEED, VARIANTS);
    for operator in required {
        assert!(
            rows.iter()
                .any(|r| r.mutant.operator == operator
                    && matches!(r.outcome, Outcome::Assembled { .. })),
            "{operator}: no mutant reached the classifier"
        );
    }
    let dimensions: std::collections::BTreeSet<Field> = rows
        .iter()
        .filter(|r| matches!(r.grade, Grade::Caught { .. }))
        .flat_map(|r| match &r.mutant.expectation {
            Expectation::Weakening(targets) => targets.iter().map(|t| t.field).collect(),
            Expectation::Control => Vec::new(),
        })
        .collect();
    assert_eq!(dimensions.len(), 7, "{dimensions:?}");
}

#[test]
fn the_bases_are_exactly_the_t09_pinned_contracts_and_every_mutant_is_a_real_edit() {
    let bases = bases();
    assert_eq!(
        bases.len(),
        3,
        "the T09 baseline pins three contracts today"
    );
    for base in &bases {
        decode(&base.document).expect("a committed contract decodes");
    }
    let mutants = generate(SEED, &bases, VARIANTS);
    let again = generate(SEED, &bases, VARIANTS);
    assert_eq!(mutants.len(), again.len());
    for (m, n) in mutants.iter().zip(&again) {
        assert_eq!(m.id, n.id);
        assert_eq!(
            m.document, n.document,
            "{}: the generator is deterministic",
            m.id
        );
        let base = bases.iter().find(|b| b.label == m.base).expect("a base");
        assert_ne!(
            m.document.to_canonical_bytes(),
            base.document.to_canonical_bytes(),
            "{}: a mutant must change the document",
            m.id
        );
    }
    let mut ids: Vec<&str> = mutants.iter().map(|m| m.id.as_str()).collect();
    ids.sort_unstable();
    ids.dedup();
    assert_eq!(ids.len(), mutants.len(), "mutant ids are unique");
}

#[test]
fn the_generator_is_written_apart_from_the_classifier() {
    // The corpus is held out only if its generator cannot see what it grades.
    for forbidden in [
        "continuum_semantic_diff",
        "change_policy",
        "Relation",
        "PolicyTable",
        "PolicyDecision",
        "PolicyField",
        "assemble(",
        "IntentContract",
        "classify",
    ] {
        assert!(
            !GENERATOR_SOURCE.contains(forbidden),
            "the generator names {forbidden:?}"
        );
    }
    let imports: Vec<&str> = GENERATOR_SOURCE
        .lines()
        .filter(|line| line.starts_with("use "))
        .collect();
    assert_eq!(
        imports,
        [
            "use std::collections::BTreeMap;",
            "use continuum_intent::canonical_json::Json;"
        ]
    );
}

#[test]
fn negative_the_scorer_rejects_a_blind_classifier_and_a_wrong_direction() {
    // The zero-miss result is only evidence if the scorer can fail. Feed it the
    // outcomes of three exploit classifiers and require a miss from each.
    let weakening = Expectation::Weakening(vec![generator::Target {
        field: Field::Properties,
        direction: Direction::WeakensProperty,
    }]);
    // 1. Blind: sees nothing, allows everything.
    let blind = Outcome::Assembled {
        records: Vec::new(),
        locked: PolicyDecision::Allow,
        locked_observed: PolicyDecision::Allow,
        own: PolicyDecision::Allow,
    };
    assert!(matches!(grade(&weakening, &blind), Grade::Miss(_)));
    // 2. Wrong direction: reads the weakening as a strengthening. Blocked under the
    //    locked policy, but still a miss, because an own `no-*` verb or a future
    //    policy would admit it.
    let wrong = Outcome::Assembled {
        records: vec![Record {
            field: PolicyField::Properties,
            unit: Some("Agreement".to_owned()),
            relation: Relation::Strengthened,
        }],
        locked: PolicyDecision::Block,
        locked_observed: PolicyDecision::Block,
        own: PolicyDecision::Block,
    };
    assert_eq!(
        grade(&weakening, &wrong),
        Grade::Miss("target field not flagged")
    );
    // 3. Right record, wrong verdict: the classification is correct and the
    //    policy lets it through. A silent pass.
    let leaky = Outcome::Assembled {
        records: vec![Record {
            field: PolicyField::Properties,
            unit: Some("Agreement".to_owned()),
            relation: Relation::Weakened,
        }],
        locked: PolicyDecision::Allow,
        locked_observed: PolicyDecision::Block,
        own: PolicyDecision::Block,
    };
    assert!(matches!(grade(&weakening, &leaky), Grade::Miss(r) if r.starts_with("silent")));
    // 4. A flag on the wrong field does not count for the target field.
    let elsewhere = Outcome::Assembled {
        records: vec![Record {
            field: PolicyField::Bounds,
            unit: None,
            relation: Relation::Contracted,
        }],
        locked: PolicyDecision::Block,
        locked_observed: PolicyDecision::Block,
        own: PolicyDecision::Block,
    };
    assert_eq!(
        grade(&weakening, &elsewhere),
        Grade::Miss("target field not flagged")
    );
    // And the positive case grades as caught, so the scorer is not a constant.
    let right = Outcome::Assembled {
        records: vec![Record {
            field: PolicyField::Properties,
            unit: Some("Agreement".to_owned()),
            relation: Relation::Weakened,
        }],
        locked: PolicyDecision::Block,
        locked_observed: PolicyDecision::Block,
        own: PolicyDecision::Block,
    };
    assert_eq!(grade(&weakening, &right), Grade::Caught { affirmed: true });
}
